import { Component, ComponentInterface, Element, h, Host, Prop } from '@stencil/core';
import { fromEvent, merge, Observable, Subject, takeUntil } from 'rxjs';
import { MenuGroupMode } from '../../../types';

/**
 * @slot label - named slot 'label', for the menu group label
 */
@Component({
  tag: 'groupui-menu-group',
  styleUrl: 'menu-group.scss',
  shadow: true,
})
export class MenuGroup implements ComponentInterface {
  @Element() private host: HTMLElement;

  /**
   * The mode of menu group, which affects selection behavior
   */
  @Prop({ reflect: true }) readonly mode: MenuGroupMode = 'default';

  private destroy = new Subject<void>();

  private menuItemsChanged = new Subject<void>();

  private menuItemClicked = new Observable<Event>();

  private menuItems(): HTMLGroupuiMenuItemElement[] {
    return Array.from(this.host.querySelectorAll(':scope > groupui-menu-item'));
  }

  private menuItemsSlot(): HTMLSlotElement {
    return this.host.shadowRoot.querySelector('slot:not([name])');
  }

  private createMenuItemClickedListener() {
    const clickListeners = this.menuItems().map((item) => {
      return fromEvent(item, 'click');
    });
    this.menuItemClicked = merge(...clickListeners).pipe(takeUntil(merge(this.destroy, this.menuItemsChanged)));
  }

  componentDidLoad() {
    this.createMenuItemClickedListener();
    this.createMenuItemsChangedListener();
    this.listenToMenuItemClicked();
    this.listenToMenuItemsChanged();
  }

  private listenToMenuItemClicked() {
    this.menuItemClicked.subscribe((event: Event) => {
      const clickedItem = event.currentTarget as HTMLElement;
      if (this.isItemTriggerElement(clickedItem)) {
        return;
      }
      if (this.mode === 'radio') {
        this.menuItems().forEach((item) => {
          item.removeAttribute('active');
        });
        clickedItem.setAttribute('active', '');
        this.closeAllMenus();
      }
      if (this.mode === 'multiple') {
        clickedItem.toggleAttribute('active');
      }
      if (this.mode === 'default' || !this.mode) {
        this.closeAllMenus();
      }
    });
  }

  private closeAllMenus() {
    this.allMenus().forEach((menu) => {
      menu.removeAttribute('visible');
    });
  }

  private allMenus(): HTMLGroupuiMenuElement[] {
    if (!this.menu()) {
      return [];
    }
    const parentMenus: HTMLGroupuiMenuElement[] = [];
    let parentMenu = this.host.parentElement.closest('groupui-menu');
    while (parentMenu !== null) {
      parentMenus.push(parentMenu);
      parentMenu = parentMenu.parentElement.closest('groupui-menu');
    }
    return [this.menu(), ...parentMenus];
  }

  private isItemTriggerElement(item: HTMLElement): boolean {
    return item.getAttribute('slot') === 'trigger';
  }

  private menu(): HTMLGroupuiMenuElement | null {
    return this.host.closest('groupui-menu') as HTMLGroupuiMenuElement;
  }

  private listenToMenuItemsChanged() {
    this.menuItemsChanged.subscribe(() => {
      this.createMenuItemClickedListener();
      this.listenToMenuItemClicked();
      this.host.dispatchEvent(new CustomEvent('MenuGroupOnSlotChange'));
    });
  }

  private createMenuItemsChangedListener() {
    fromEvent(this.menuItemsSlot(), 'slotchange')
      .pipe(takeUntil(this.destroy))
      .subscribe(() => {
        this.menuItemsChanged.next();
      });
  }

  disconnectedCallback() {
    this.destroy.next();
    this.destroy.complete();
  }

  private isLabelSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="label"]');
  }

  render() {
    return (
      <Host>
        {this.isLabelSlotProvided() && (
          <label id="label">
            <slot name="label"></slot>
          </label>
        )}
        <slot></slot>
      </Host>
    );
  }
}
